13	import org.springframework.samples.petclinic.rest.validation.LocalityResolver;
14	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
31	    @Mapping(target = "identityKey", expression = "java(owner.getIdentityKey())")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    Owner toOwner(OwnerDto ownerDto);
35	
36	    /**
37	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
38	     */
39	    default String formatDisplayName(Owner owner) {
40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /**
44	     * Formats the owner's initials as the upper-cased first letters of firstName and
45	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
46	     */
47	    default String formatInitials(Owner owner) {
48	        return initial(owner.getFirstName()) + initial(owner.getLastName());
49	    }
50	
51	    /** The upper-cased first letter of {@code name} followed by a dot. */
52	    private String initial(String name) {
53	        return Character.toUpperCase(name.charAt(0)) + ".";
54	    }
55	
56	    /**
57	     * Derives the owner's locality (canonical region) from its city via the fixed
58	     * city-to-region table, yielding {@code "UNKNOWN"} for any city not in the table.
59	     */
60	    default String resolveLocality(Owner owner) {
61	        return LocalityResolver.resolve(owner.getCity());
62	    }
63	
64	    /**
65	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
66	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
67	     */
68	    default String formatMembershipNumber(Owner owner) {
69	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
70	    }
71	
72	    /**
73	     * Resolves the owner's numeric membership level, assigned on creation: starts at {@code 1},
74	     * plus {@code 1} when an email is present, plus {@code 1} when the owner has no namesakes
75	     * (namesakeCount is 0), capped at {@code 3} (level {@code 4} is reserved for tenure).
76	     */
77	    default Integer resolveMembershipLevel(Owner owner) {
78	        int level = 1;
79	        if (hasEmail(owner)) {
80	            level++;
81	        }
82	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
83	            level++;
84	        }
85	        return Math.min(level, 3);
86	    }
87	
88	    /**
89	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
90	     * present, otherwise {@code "PHONE"}.
91	     */
92	    default String resolveContactPreference(Owner owner) {
93	        return hasEmail(owner) ? "EMAIL" : "PHONE";
94	    }
95	
96	    /** Whether the owner has a non-blank email address. */
97	    private boolean hasEmail(Owner owner) {
98	        return owner.getEmail() != null && !owner.getEmail().isBlank();
99	    }
100	
101	    @Mapping(target = "id", ignore = true)
102	    @Mapping(target = "pets", ignore = true)
103	    @Mapping(target = "householdId", ignore = true)
104	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
105	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
106	    Owner toOwner(OwnerFieldsDto ownerDto);
107	
108	    /**
109	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
110	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
111	     */
112	    @Named("normalizeAddress")
113	    default String normalizeAddress(String address) {
114	        return AddressNormalizer.normalize(address);
115	    }
116	
117	    /**
118	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
119	     * the raw value normalizes to a valid E.164 number.
120	     */
121	    @Named("normalizeTelephone")
122	    default String normalizeTelephone(String telephone) {
123	        return TelephoneNormalizer.toE164(telephone);
124	    }
125	
126	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
127	
128	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
129	
130	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
131	        OwnerPageDto ownerPageDto = new OwnerPageDto();
132	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
133	        ownerPageDto.setPage(ownerPage.getNumber());
134	        ownerPageDto.setSize(ownerPage.getSize());
135	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
136	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
137	        return ownerPageDto;
138	    }
139	}
